package org.retrobridge.storeinstaller;
import android.content.*;import android.content.pm.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import java.io.*;import java.lang.reflect.*;import java.security.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;

/** Narrow system installer for the owner's Store; no network, boot work or launcher. */
public final class VerifiedInstaller extends ContentProvider {
 static final String STORE="org.retrobridge.play2012",PERMISSION="org.retrobridge.storeinstaller.INSTALL_VERIFIED";
 final AtomicBoolean busy=new AtomicBoolean();
 public boolean onCreate(){return true;}
 void caller(){getContext().enforceCallingPermission(PERMISSION,"Store permission required");String[] names=getContext().getPackageManager().getPackagesForUid(Binder.getCallingUid());if(names==null||names.length!=1||!STORE.equals(names[0]))throw new SecurityException("Store caller required");}
 static String hash(File f)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");InputStream in=new FileInputStream(f);try{byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1)d.update(b,0,n);}finally{in.close();}return hex(d.digest());}
 static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format(Locale.US,"%02x",v&255));return s.toString();}
 public Bundle call(String method,String arg,Bundle input){caller();Bundle result=new Bundle();if("status".equals(method)){result.putBoolean("ready",getContext().getPackageManager().checkPermission("android.permission.INSTALL_PACKAGES",getContext().getPackageName())==PackageManager.PERMISSION_GRANTED);return result;}if(!"install".equals(method)||input==null)throw new IllegalArgumentException("Unsupported operation");if(!busy.compareAndSet(false,true)){result.putInt("code",-1000);result.putString("error","Another installation is running");return result;}
  File copy=null;boolean finished=false;long identity=Binder.clearCallingIdentity();
  try{String pkg=input.getString("package"),sha=input.getString("sha256"),signer=input.getString("signerSha256");int version=input.getInt("versionCode");long size=input.getLong("size");
   if(pkg==null||!pkg.matches("[A-Za-z0-9_.]+")||sha==null||!sha.matches("[a-f0-9]{64}")||signer==null||!signer.matches("[a-f0-9]{64}")||size<=0||size>1000000000L)throw new IOException("Invalid installer request");
   if(pkg.equals(getContext().getPackageName()))throw new IOException("Helper updates require setup");
   File folder=new File(Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS),"Galaxy Store").getCanonicalFile();File source=new File(folder,pkg+"-"+version+".apk").getCanonicalFile();if(!source.getParentFile().equals(folder)||!source.isFile()||source.length()!=size)throw new IOException("Installer file is missing");
   File cache=getContext().getCacheDir();cache.setExecutable(true,false);copy=File.createTempFile("verified-",".apk",cache);InputStream in=new FileInputStream(source);FileOutputStream out=new FileOutputStream(copy);try{byte[] b=new byte[32768];long count=0;int n;while((n=in.read(b))!=-1){count+=n;if(count>size)throw new IOException("Installer size changed");out.write(b,0,n);}out.getFD().sync();if(count!=size)throw new IOException("Incomplete installer");}finally{in.close();out.close();}
   if(!hash(copy).equals(sha))throw new IOException("Installer checksum mismatch");PackageManager pm=getContext().getPackageManager();PackageInfo pi=pm.getPackageArchiveInfo(copy.toString(),PackageManager.GET_SIGNATURES);if(pi==null||!pkg.equals(pi.packageName)||version!=pi.versionCode||pi.signatures==null||pi.signatures.length!=1||!hex(MessageDigest.getInstance("SHA-256").digest(pi.signatures[0].toByteArray())).equals(signer))throw new IOException("Installer signature mismatch");
   try{PackageInfo old=pm.getPackageInfo(pkg,PackageManager.GET_SIGNATURES);if((old.applicationInfo.flags&ApplicationInfo.FLAG_SYSTEM)!=0)throw new IOException("System app replacement is disabled");if(old.versionCode>version)throw new IOException("A newer version is already installed");if(old.signatures==null||old.signatures.length!=1||!old.signatures[0].equals(pi.signatures[0]))throw new IOException("Installed app has a different signature");}catch(PackageManager.NameNotFoundException absent){}
   copy.setReadable(true,false);final CountDownLatch done=new CountDownLatch(1);final AtomicInteger code=new AtomicInteger(-1001);final File installedFile=copy;
   final Binder callback=new Binder(){protected boolean onTransact(int what,Parcel data,Parcel reply,int flags)throws RemoteException{if(what==IBinder.INTERFACE_TRANSACTION){if(reply!=null)reply.writeString("android.content.pm.IPackageInstallObserver");return true;}if(what==IBinder.FIRST_CALL_TRANSACTION){data.enforceInterface("android.content.pm.IPackageInstallObserver");data.readString();code.set(data.readInt());installedFile.delete();done.countDown();if(reply!=null)reply.writeNoException();return true;}return super.onTransact(what,data,reply,flags);}};
   Class<?> observer=Class.forName("android.content.pm.IPackageInstallObserver");Object proxy=java.lang.reflect.Proxy.newProxyInstance(observer.getClassLoader(),new Class[]{observer},new InvocationHandler(){public Object invoke(Object p,Method m,Object[] args){if(m.getName().equals("asBinder"))return callback;if(m.getName().equals("packageInstalled")){code.set((Integer)args[1]);installedFile.delete();done.countDown();return null;}return null;}});
   pm.getClass().getMethod("installPackage",Uri.class,observer,int.class,String.class).invoke(pm,Uri.fromFile(copy),proxy,2,STORE);
   finished=done.await(180,TimeUnit.SECONDS);result.putInt("code",code.get());if(!finished)result.putString("error","Installation is taking longer than expected");else if(code.get()!=1)result.putString("error","Android could not install this app ("+code.get()+")");
  }catch(Exception e){finished=true;result.putInt("code",-1002);result.putString("error",e instanceof InvocationTargetException?"System installer unavailable":e.getMessage());}
  finally{if(finished&&copy!=null)copy.delete();Binder.restoreCallingIdentity(identity);busy.set(false);}return result;
 }
 public Cursor query(Uri u,String[] p,String s,String[] a,String o){throw new UnsupportedOperationException();}public String getType(Uri u){return null;}public Uri insert(Uri u,ContentValues v){throw new UnsupportedOperationException();}public int delete(Uri u,String s,String[] a){throw new UnsupportedOperationException();}public int update(Uri u,ContentValues v,String s,String[] a){throw new UnsupportedOperationException();}
}
